pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool initialPause) public {
        // Prepare: optionally pause or unpause
        if (initialPause) {
            // First need to grant manager role to this contract (msg.sender) to call pause
            // Simpler: just use vm.prank to impersonate admin
            // We'll just test both cases directly via unpause/pause calls, but they need proper roles.
            // To avoid role complexity, we can directly manipulate internal state via vm.store? Not allowed.
            // Instead, we'll just check that paused() returns the expected value after known operations.
            // The bug is that paused() returns !_paused, so we can test that pausing then calling paused() returns true.
            // But we cannot pause without roles. We can call addNodeDelegatorContractToQueue which doesn't change paused state.
            // So we rely on default (unpaused). The rule: paused() must return false when unpaused.
            // Since we cannot change pause state easily without admin/manager, we just test the default.
            // However, the bug is always returning negation, so for default (paused = false) it would return true, which is wrong.
            // So the rule is: paused() returns false when just deployed.
        }
        // The property: paused() should return false at start (no pause called)
        assertTrue(!c.paused());
    }
}

